    /**
     * Method to retrieve the Warehouse via WarehouseFetchOneSummary
     * @param 	summary WarehouseFetchOneSummary 
     * @return 	WarehouseFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Warehouse getWarehouse( WarehouseFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "WarehouseFetchOneSummary arg cannot be null" );
    	
    	Warehouse entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Warehouse
        	// --------------------------------------
        	CompletableFuture<Warehouse> futureEntity = queryGateway.query(new FindWarehouseQuery( new LoadWarehouseFilter( summary.getWarehouseId() ) ), ResponseTypes.instanceOf(Warehouse.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Warehouse with id " + summary.getWarehouseId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


